pub(super) fn requirement_snapshots(build: &Build, data: &BuildData) -> Vec<(String, f64)> {
    let mut values = BTreeMap::<String, f64>::new();
    let mut maximum = |category: &str, requirements: [f64; 3]| {
        for (attr, requirement) in ["Str", "Dex", "Int"].into_iter().zip(requirements) {
            let value = values
                .entry(format!("{category}Requirement{attr}"))
                .or_default();
            *value = value.max(requirement);
        }
    };
    for (_, item) in build.equipped_items() {
        let Some(base) = data.base_item(&item.base.to_string()) else {
            continue;
        };
        let mut local = ModDb::new();
        if let Some(rules) = data.parser_rules.as_ref() {
            for line in item
                .implicit_texts
                .iter()
                .chain(&item.modifier_texts)
                .chain(&item.enchant_texts)
            {
                // A partly read line (`ParseOutcome::into_applicable`) changes no requirement.
                if let Ok(mods) = parse_mod_engine(line, rules).into_applicable(line) {
                    local.add_list(mods);
                }
            }
        }
        let cfg = CalcConfig::new();
        let raw = [
            base.req_str as f64,
            base.req_dex as f64,
            base.req_int as f64,
        ];
        let conversion = ["Strength", "Dexterity", "Intelligence"].map(|attr| {
            local.sum(
                ModType::Base,
                &cfg,
                &[ModName::from(format!(
                    "AttributeRequirementsConvertedTo{attr}"
                ))],
            ) / 100.0
        });
        let total: f64 = raw.iter().sum();
        let converted: f64 = conversion.iter().sum();
        let requirements = std::array::from_fn(|i| {
            if local.flag(&cfg, "NoAttributeRequirements") {
                return 0.0;
            }
            let names = [ModName::from(format!(
                "{}Requirement",
                ["Str", "Dex", "Int"][i]
            ))];
            // Requirement conversion changes the base item's requirements;
            // a local flat requirement is added in its own attribute afterwards.
            let base = raw[i] * (1.0 - converted)
                + total * conversion[i]
                + local.sum(ModType::Base, &cfg, &names);
            (base
                * (1.0 + local.sum(ModType::Inc, &cfg, &names) / 100.0)
                * local.more(&cfg, &names))
            .max(0.0)
            .floor()
        });
        let category = if base.weapon.is_none() {
            "Item"
        } else if ["Bow", "Crossbow", "Wand", "Staff", "Sceptre"]
            .iter()
            .any(|kind| base.item_class.contains(kind))
        {
            "Weapon"
        } else {
            "MeleeWeapon"
        };
        maximum(category, requirements);
    }
    let mut supports = [0.0; 3];
    for group in build.enabled_socket_groups() {
        let refs: Vec<(&str, u32)> = if group.gem_skills.is_empty() && group.gem_ids.is_empty() {
            group
                .active_skill_id
                .as_deref()
                .map(|id| (id, group.active_gem_level.unwrap_or(1)))
                .into_iter()
                .collect()
        } else if group.gem_skills.is_empty() {
            group
                .gem_ids
                .iter()
                .map(|id| (id.as_str(), group.active_gem_level.unwrap_or(1)))
                .collect()
        } else {
            group
                .gem_skills
                .iter()
                .enumerate()
                .map(|(i, gem)| {
                    (
                        gem.skill_id.as_str(),
                        group
                            .gem_requirement_levels
                            .get(i)
                            .copied()
                            .unwrap_or(gem.gem_level),
                    )
                })
                .collect()
        };
        for (index, (id, level)) in refs.into_iter().enumerate() {
            let gem = data
                .skill_gems
                .get(id)
                .or_else(|| {
                    data.gem_effects
                        .get(id)
                        .and_then(|effect| data.skill_gems.get(&effect.gem_id))
                })
                .or_else(|| {
                    data.skill_gems
                        .values()
                        .find(|gem| gem.granted_effect_id.as_deref() == Some(id))
                });
            let Some(gem) = gem else {
                continue;
            };
            if gem.is_support {
                if let Some(colour @ 1..=3) = gem.gem_colour {
                    supports[(colour - 1) as usize] += 5.0;
                }
            } else if group.source.is_none() && !(index == 0 && group.granted_level.is_some()) {
                // Added skill levels change the skill, not the gem's requirements.
                if let Some(requirements) = gem.attribute_requirements(level) {
                    maximum(
                        if gem.gem_tags.iter().any(|tag| tag == "melee") {
                            "MeleeGem"
                        } else {
                            "Gem"
                        },
                        requirements.map(f64::from),
                    );
                }
            }
        }
    }
    maximum("Support", supports);
    values.into_iter().collect()
}

impl SkillGemDef {
    /// The character level gem level `level` requires; `None` when the
    /// snapshot doesn't carry the gem's requirements.
    pub fn level_requirement(&self, level: u32) -> Option<u32> {
        let index = (level.max(1) as usize - 1).min(self.level_requirements.len().checked_sub(1)?);
        Some(self.level_requirements[index])
    }

    /// The Strength, Dexterity and Intelligence gem level `level` requires:
    /// each attribute's share of the gem (`str_pct` …) applied to the
    /// requirement of a gem needing character level L,
    /// round((5 + (L − 3) × 1.7) × (share / 100)^0.9) + 4, nothing for an
    /// attribute without a share. (The game's per-level values agree: Purity
    /// of Ice, 25% Strength and 75% Intelligence, needs 42 and 106 at gem
    /// level 18, character level 78.) `None` when the snapshot doesn't carry
    /// the gem's level requirements.
    pub fn attribute_requirements(&self, level: u32) -> Option<[u32; 3]> {
        let required_level = f64::from(self.level_requirement(level)?);
        let requirement = |share: u32| {
            if share == 0 {
                return 0;
            }
            let scaled =
                (5.0 + (required_level - 3.0) * 1.7) * (f64::from(share) / 100.0).powf(0.9);
            ((scaled + 0.5).floor() + 4.0).max(0.0) as u32
        };
        Some([
            requirement(self.str_pct),
            requirement(self.dex_pct),
            requirement(self.int_pct),
        ])
    }
}

/// A granted-effect definition (from `GrantedEffects.dat` plus foreign-key

/// Highest requirement among equipment and active gems; support gems require
/// five of their attribute each across the build. Global gem modifiers do not
/// change this cumulative support requirement.
pub fn attribute_requirements(db: &ModDb, cfg: &CalcConfig) -> [f64; 3] {
    attribute_requirement_terms(db, cfg).map(|values| values.into_iter().fold(0.0, f64::max))
}

/// Names whose increases and decreases scale one category's attribute
/// requirements: the generic name, the gem or item name, and for weapons the
/// weapon name. Shared by the requirement calculation and the Calcs views.
pub fn requirement_modifier_names(category: &str) -> Vec<ModName> {
    let mut names = vec![
        ModName::from("GlobalAttributeRequirements"),
        ModName::from(if category.ends_with("Gem") {
            "GlobalGemAttributeRequirements"
        } else {
            "GlobalItemAttributeRequirements"
        }),
    ];
    if category.ends_with("Weapon") {
        names.push(ModName::from("GlobalWeaponAttributeRequirements"));
    }
    names
}

/// The multiplier applied to a category's requirements (`Item`, `Weapon`,
/// `MeleeWeapon`, `Gem` or `MeleeGem`); `global` has the skill's flags cleared.
pub fn requirement_modifier(db: &ModDb, global: &CalcConfig, category: &str) -> f64 {
    let names = requirement_modifier_names(category);
    ((1.0 + db.sum(ModType::Inc, global, &names) / 100.0) * db.more(global, &names)).max(0.0)
}

/// The Gem, Item and Weapon requirement multipliers, in that order, read with
/// the skill's flags cleared as in [`attribute_requirement_terms`].
pub fn global_requirement_modifiers(db: &ModDb, cfg: &CalcConfig) -> [f64; 3] {
    let mut global = cfg.clone();
    global.flags = ModFlags::NONE;
    global.keyword_flags = KeywordFlags::NONE;
    ["Gem", "Item", "Weapon"].map(|category| requirement_modifier(db, &global, category))
}

/// Adjusted category requirements, after substitutions and ignored requirements.
pub fn attribute_requirement_terms(db: &ModDb, cfg: &CalcConfig) -> [[f64; 6]; 3] {
    if db.flag(cfg, "IgnoreAttributeRequirements") {
        return [[0.0; 6]; 3];
    }
    let mut global = cfg.clone();
    global.flags = ModFlags::NONE;
    global.keyword_flags = KeywordFlags::NONE;
    let stat = |name: &str| cfg.stats.get(name).copied().unwrap_or(0.0);
    let highest = ["Strength", "Dexterity", "Intelligence"]
        .map(stat)
        .into_iter()
        .fold(0.0, f64::max);
    let highest_satisfies = db.flag(
        &global,
        "GemAttributeRequirementsSatisfiedByHighestAttribute",
    );
    let strength_satisfies = db.flag(&global, "StrengthSatisfiesMeleeWeaponsAndSkills");
    ["Str", "Dex", "Int"].map(|attr| {
        let mut result = [0.0; 6];
        result[0] = stat(&format!("SupportRequirement{attr}"));
        for (index, category) in ["Item", "Weapon", "MeleeWeapon", "Gem", "MeleeGem"]
            .into_iter()
            .enumerate()
        {
            let gem = category.ends_with("Gem");
            let modifier = requirement_modifier(db, &global, category);
            let requirement = (stat(&format!("{category}Requirement{attr}")) * modifier).floor();
            if (gem && highest_satisfies && highest >= requirement)
                || (category.starts_with("Melee")
                    && strength_satisfies
                    && attr != "Str"
                    && stat("Strength") >= requirement)
            {
                continue;
            }
            result[index + 1] = requirement;
        }
        result
    })
}

